#!/usr/bin/env node
// changelog-freshness — nightly ledger-drift check (ADR-0165, implemented 13r-g / ADR-0196).
//
// Usage:
//   node scripts/changelog-freshness.mjs            # check (the default and only mode)
//   node scripts/changelog-freshness.mjs --check    # documented alias, identical behaviour
//
// CHANGELOG.md is generated by `git cliff` (`just changelog`, justfile:172). Policy
// (ARCHITECTURE.md, m17.5g) lets the committed ledger lag master by at most one open
// milestone; twice it has drifted far past that (24 entries before 12r-f, 34 before this
// slice) because nothing measured it. This script measures it, nightly.
//
// WHAT IT COMPARES — a fresh generation against the committed file, never git-log against
// the committed file. That is what makes `cliff.toml`'s `filter_unconventional = true`
// a non-issue: a commit git-cliff skips is absent from BOTH sides and can never read as
// drift (ADR-0165's named subtlety). Its cost, recorded honestly: a slice whose squash
// subject is not a Conventional Commit produces no entry at all, so this counter
// structurally cannot see that class of staleness.
//
// WHY A CONJUNCTION AND NOT A THRESHOLD — see THRESHOLDS below. A bare entry-count
// threshold cannot separate a healthy weekly wave from real rot in this repo.
//
// EXIT CODES (house convention, scripts/adr-digest.mjs:840-861): 0 = fresh or advisory,
// 1 = drift the ledger owner must fix, 2 = environment / the script cannot trust itself.
//
// IMPORTANT: NO `new RegExp(...)` anywhere — only literal regex literals and String
// methods. The remote-only Semgrep gate (detect-non-literal-regexp) has bitten this
// project 3x and `just ci` runs no Semgrep, so a violation is only caught on the PR.
import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

// ---------------------------------------------------------------------------
// THRESHOLDS
//
// Provenance (measured 2026-08-15 by replaying the real nightly signal: `git cliff` at
// each of the last 150 master commits, diffed against that commit's committed
// CHANGELOG.md, collapsed to one value per calendar night). `missing` per night over
// 2026-07-15..2026-08-15:
//
//   1, 3, 12, 22, 11, 19, 24, 26, 26, 4, 17, 18, 23, 23, 23, 25, 8,
//   14, 15, 15, 17, 20, 21, 4, 12, 18, 20, 20, 20, 21, 33, 34
//
// The drift is a weekly sawtooth: it reaches 20-26 on a perfectly healthy wave and then
// resets to 1-8 at the milestone-close regen. There is therefore NO single count that
// separates "healthy wave" from "rot": `> 15` reds 21 of 32 nights (66%), `> 25` reds 4
// of 32 but misses half the real episodes. A 66%-red nightly is how the OTHER four jobs
// stop being read — exactly the failure ADR-0183 records (mutation-server red five
// consecutive nights, unnoticed, with no notification wiring) and the same
// nag-then-bypass mode ADR-0165 rejected the per-PR gate for.
//
// So the failure signal is a CONJUNCTION: far behind AND behind for days. That fires on
// 5 of the 32 nights (07-30, 08-06, 08-13, 08-14, 08-15) — one night of lead time per
// wave, then escalating redness only while the wave stays unreconciled, which is the
// actual pathology. Lowering either number is safe; RAISING either one requires amending
// ADR-0196. (This is a convention, not a mechanical ratchet: pinning it would take an
// eval, and `evals/**` is outside slice 13r-g's declared touches — named follow-up in
// ADR-0196.)
export const LAG_FAIL_ENTRIES = 15;
export const LAG_FAIL_AGE_DAYS = 6;
// Advisory-only. Printed so the nightly log shows the wave BUILDING, which is the whole
// point of a signal nobody is paged for.
export const LAG_WARN_ENTRIES = 8;
// A regen run at a branch TIP bakes local commit subjects that the squash-merge then
// rewrites, leaving a handful of committed entries no generation can reproduce. That has
// already happened once here (34250d5: committed `- ARCHITECTURE.md + ADR-0080 knowledge
// bundle doc` vs generated `- ARCHITECTURE.md + ADR-0080 + CHANGELOG — closes M8.95
// knowledge-bundle milestone (#105)`), so a small `extra` is a KNOWN, self-inflicted,
// low-stakes shape and gets an advisory. A `cliff.toml` template edit or a git-cliff
// version change flips hundreds at once — that is the shape worth a red.
export const EXTRA_HARD_FLOOR = 3;
// Fail-closed floor on the generation itself. History here is append-only (squash-merge
// only; force-push is hook-blocked), so a generation can never shrink. 341 = measured at
// origin/master@7eb6980. This single number kills the whole vacuous-green family at once:
// git-cliff absent with its error swallowed to '' (0 entries), a shallow checkout
// (1 entry), a truncated read.
export const MIN_GENERATED_ENTRIES = 341;
// `node --test <file>` EXITS 0 WHEN THE FILE DEFINES ZERO TESTS (verified, node 24.13.1:
// it counts the file itself as one passing test). So a commented-out suite is a green
// nightly forever. Same countermeasure as evals/observability-stack-config.eval.mjs:334-349
// ("an EXPLICIT list, never a glob ... '0 files, 0 failures' exits 0"), relocated into
// this script because `evals/**` is outside this slice's touches.
export const SIBLING_TEST_FILE = 'changelog-freshness.test.mjs';
export const SIBLING_TEST_MARKER = '\n  it(';
// Floor, not an equality pin: set below the committed count (66 at 13r-g) so ordinary
// test consolidation does not red the nightly, but far enough above zero that a
// commented-out or emptied suite cannot pass.
export const MIN_SIBLING_TESTS = 50;
// Every generated entry should be reproducible from some commit subject via
// entryTextForSubject — measured 341/341 (100%) at origin/master@7eb6980. The floor
// guards the AGE arm of the conjunction: if that transform silently stops matching,
// oldestMissingAgeDays returns null on every night, `stale` becomes unreachable, and the
// gate is permanently green — the same failure class as deriving age from file mtime.
export const MIN_MAPPED_FRACTION = 0.9;

const LOG_PREFIX = 'changelog-freshness: ';
const TITLE_LINE = '# Changelog';
const HEADING_PREFIX = '### ';
const ENTRY_PREFIX = '- ';
// U+0000 cannot occur in a changelog line, so it can never collide with entry text.
export const KEY_SEPARATOR = '\u0000';
const MS_PER_DAY = 86400000;

// ---------------------------------------------------------------------------
// Pure core
// ---------------------------------------------------------------------------

// Right-strip every line (kills CRLF and trailing-space noise) and drop trailing blank
// lines at EOF. Deliberately NOT a whole-text trim and NOT blank-line collapsing: a blank
// line inserted mid-document is a real rendering difference and must stay visible.
function normalizeLines(text) {
  return text.split('\n').map((line) => line.replace(/\s+$/, ''));
}

export function normalizeText(text) {
  return normalizeLines(text).join('\n').replace(/\n+$/, '');
}

export function entryKey(group, entryText) {
  return `${group}${KEY_SEPARATOR}${entryText}`;
}

export function entryTextFromKey(key) {
  const idx = key.indexOf(KEY_SEPARATOR);
  return idx === -1 ? key : key.slice(idx + KEY_SEPARATOR.length);
}

// Multiset, not a Set: 25 entries in the real file carry no `(#NNN)` suffix, so two
// commits can render byte-identical lines within one group and a Set would under-count
// the lag. Group-scoped keys: the only thing that can see a `cliff.toml` group rename,
// and the only thing that reports an entry moving between groups as a real change.
export function parseChangelogEntries(text) {
  const entries = new Map();
  let group = null;
  for (const line of normalizeLines(text)) {
    if (line.startsWith(HEADING_PREFIX)) {
      group = line.slice(HEADING_PREFIX.length).trim();
      continue;
    }
    // An entry before the first heading has no group; it is an environment error, not an
    // entry (findStructuralProblems reports it). Counting it would mint a phantom key.
    if (!line.startsWith(ENTRY_PREFIX) || group === null) continue;
    const key = entryKey(group, line.slice(ENTRY_PREFIX.length).trim());
    entries.set(key, (entries.get(key) ?? 0) + 1);
  }
  return entries;
}

// Anything here means the input is not a changelog this script can reason about — the
// shell exits 2 (environment) rather than emitting a confident freshness verdict.
export function findStructuralProblems(text) {
  const problems = [];
  let seenHeading = false;
  let entryCount = 0;
  let lineNo = 0;
  for (const line of normalizeLines(text)) {
    lineNo += 1;
    if (line === '' || line === TITLE_LINE) continue;
    if (line.startsWith(HEADING_PREFIX)) {
      seenHeading = true;
      continue;
    }
    if (line.startsWith(ENTRY_PREFIX)) {
      if (seenHeading) entryCount += 1;
      else problems.push(`line ${lineNo}: entry before the first '${HEADING_PREFIX}' heading`);
      continue;
    }
    problems.push(
      `line ${lineNo}: not blank, '${TITLE_LINE}', a heading, or an entry: ${line.slice(0, 60)}`,
    );
  }
  if (entryCount === 0) problems.push('no changelog entries found');
  return problems;
}

// Conventional-commit subject -> the entry text git-cliff renders for it. Verified to
// reproduce git-cliff exactly at origin/master@7eb6980: 341 of 341 generated entries map
// back to a `git log --format=%s` subject, and the 7 unmapped subjects are precisely the
// ones git-cliff itself reports as "7 commit(s) were skipped due to parse error(s)".
// `null` = not a Conventional Commit, i.e. legitimately absent from the ledger.
export function entryTextForSubject(subject) {
  const match = /^([A-Za-z][A-Za-z0-9._-]*)(\([^)]*\))?(!)?: (.+)$/.exec(subject);
  if (match === null) return null;
  const description = match[4];
  // cliff.toml renders `{{ commit.message | upper_first }}`.
  return description.charAt(0).toUpperCase() + description.slice(1);
}

// How long the ledger has been behind, measured from the OLDEST commit whose entry is
// still missing. Clock is INJECTED (nowMs) — determinism invariant; there is deliberately
// no Date.now() in this function.
//
// NEVER derive this from `statSync('CHANGELOG.md').mtimeMs`: in a fresh actions/checkout
// every file's mtime is the checkout time, so the age would always be ~0 and the gate
// would be permanently, silently green. `git log -1 --format=%cI -- CHANGELOG.md` is
// likewise wrong — any cosmetic touch resets it.
export function oldestMissingAgeDays({ missingTexts, commits, nowMs }) {
  const wanted = new Set(missingTexts);
  let oldestMs = null;
  for (const commit of commits) {
    const text = entryTextForSubject(commit.subject);
    if (text === null || !wanted.has(text)) continue;
    const ms = Date.parse(commit.iso);
    if (Number.isNaN(ms)) continue;
    if (oldestMs === null || ms < oldestMs) oldestMs = ms;
  }
  if (oldestMs === null) return null;
  return (nowMs - oldestMs) / MS_PER_DAY;
}

// Entries present in `a` beyond `b`'s count for the same key.
function multisetDifference(a, b) {
  const out = [];
  for (const [key, count] of a) {
    const covered = b.get(key) ?? 0;
    for (let i = covered; i < count; i += 1) out.push(key);
  }
  return out;
}

export const DEFAULT_THRESHOLDS = {
  failEntries: LAG_FAIL_ENTRIES,
  failAgeDays: LAG_FAIL_AGE_DAYS,
  warnEntries: LAG_WARN_ENTRIES,
  extraHardFloor: EXTRA_HARD_FLOOR,
};

// Verdict precedence is load-bearing and is the place bugs live — vacuous beats drift
// beats stale beats lagging beats rendering beats fresh.
export function classifyChangelogDrift({
  generatedText,
  committedText,
  ageDays = null,
  thresholds,
}) {
  const t = { ...DEFAULT_THRESHOLDS, ...(thresholds ?? {}) };
  const generated = parseChangelogEntries(generatedText);
  const committed = parseChangelogEntries(committedText);
  const missing = multisetDifference(generated, committed);
  const extra = multisetDifference(committed, generated);
  // `rendersIdentically` is carried on the result even when the verdict is decided by a
  // higher-precedence rule: `lagging` outranks `rendering`, so without this field a
  // git-cliff version bump that lands MID-WAVE (lag >= warn) would be reported as a
  // routine advisory and its rendering drift would be invisible. formatVerdict always
  // names it.
  const result = {
    verdict: 'fresh',
    missing,
    extra,
    lag: missing.length,
    ageDays,
    rendersIdentically: normalizeText(generatedText) === normalizeText(committedText),
  };

  // Either side empty is never a statement about freshness — it is a broken input.
  if (generated.size === 0 || committed.size === 0) {
    result.verdict = 'vacuous';
    return result;
  }
  if (extra.length > t.extraHardFloor) {
    result.verdict = 'drift';
    return result;
  }
  // The conjunction. `ageDays === null` (no missing entry could be dated) deliberately
  // does NOT fail: an undatable lag means the subject->entry map went stale, which the
  // shell's environment guards are responsible for, not the freshness verdict.
  if (missing.length >= t.failEntries && ageDays !== null && ageDays >= t.failAgeDays) {
    result.verdict = 'stale';
    return result;
  }
  if (missing.length >= t.warnEntries || extra.length > 0) {
    result.verdict = 'lagging';
    return result;
  }
  // Same entries, different bytes: a generator/template difference the ledger owner still
  // has to reconcile, and the only thing an entry-set comparison would otherwise miss.
  if (
    missing.length === 0 &&
    extra.length === 0 &&
    normalizeText(generatedText) !== normalizeText(committedText)
  ) {
    result.verdict = 'rendering';
    return result;
  }
  return result;
}

// Fail-closed: an unknown verdict is an environment error, never a pass.
export function exitCodeForVerdict(verdict) {
  if (verdict === 'fresh' || verdict === 'lagging') return 0;
  if (verdict === 'stale' || verdict === 'drift' || verdict === 'rendering') return 1;
  return 2;
}

export function formatVerdict(result) {
  const lines = [];
  const lag = result.lag;
  const age = result.ageDays === null ? 'undatable' : `${result.ageDays.toFixed(1)}d`;
  // Machine-greppable trailer first: the nightly log is read by grep far more often than
  // by a human, and the prose below is free to change.
  lines.push(`verdict=${result.verdict} lag=${lag} age=${age} extra=${result.extra.length}`);
  switch (result.verdict) {
    case 'fresh':
      lines.push(
        `ledger is fresh (${lag} behind, tolerance ${LAG_FAIL_ENTRIES} entries AND ${LAG_FAIL_AGE_DAYS} days)`,
      );
      break;
    case 'lagging':
      lines.push(
        `ledger is ${lag} entries behind, oldest missing ${age} — within policy (fails at ${LAG_FAIL_ENTRIES} entries AND ${LAG_FAIL_AGE_DAYS} days)`,
      );
      break;
    case 'stale':
      lines.push(
        `STALE: ledger is ${lag} entries behind and has been for ${age} (fails at ${LAG_FAIL_ENTRIES} entries AND ${LAG_FAIL_AGE_DAYS} days)`,
      );
      lines.push('remedy: run `just changelog` on master and commit CHANGELOG.md');
      break;
    case 'drift':
      lines.push(
        `GENERATOR DRIFT: ${result.extra.length} committed entries are not reproducible from history (floor ${EXTRA_HARD_FLOOR})`,
      );
      lines.push(
        'candidate causes: a cliff.toml/template edit, a git-cliff version change, or a hand-edited CHANGELOG.md',
      );
      break;
    case 'rendering':
      lines.push(
        'RENDERING DRIFT: entries match but the rendered file differs from a fresh generation',
      );
      lines.push('remedy: run `just changelog` on master and commit CHANGELOG.md');
      break;
    default:
      lines.push(
        `VACUOUS: one side parsed to zero entries (generated-missing=${lag}) — refusing to report freshness`,
      );
      break;
  }
  if (result.extra.length > 0 && result.verdict !== 'drift') {
    lines.push(
      `note: ${result.extra.length} committed entries are not reproducible from history — the branch-tip-regen signature (ADR-0196); regen from master`,
    );
  }
  // Deliberately NOT reported under `lagging`: once even one entry is missing the two
  // texts necessarily differ, so "rendering also differs" carries no information there.
  // A mid-wave git-cliff version bump surfaces as `extra` instead (entries flip on both
  // sides at once), which the note above names. `rendersIdentically` stays on the result
  // for callers that want the raw signal.
  // Name the offending entries, not just their count — a bare number sends the reader
  // back to run the tool themselves.
  for (const key of result.extra.slice(0, 3))
    lines.push(`  not-in-history: ${entryTextFromKey(key)}`);
  for (const key of result.missing.slice(0, 3)) lines.push(`  behind: ${entryTextFromKey(key)}`);
  return lines.map((line) => LOG_PREFIX + line).join('\n');
}

// ---------------------------------------------------------------------------
// Proof-of-teeth. Runs on EVERY invocation, before any file or subprocess I/O, because
// `just ci` cannot run this script (`justfile` and `evals/**` are outside slice 13r-g's
// touches) — so these fixtures are the only per-run proof the comparator still works.
// Each case names the wrong implementation it kills; each was verified to kill it.
// ---------------------------------------------------------------------------
const G = (...entries) =>
  `# Changelog\n\n### Features\n\n${entries.map((e) => `- ${e}`).join('\n')}\n`;
const seq = (n, from = 0) => Array.from({ length: n }, (_, i) => `entry ${i + from}`);

const SELF_TEST_CASES = [
  {
    name: 'identical entries, different layout -> fresh (kills: byte-diff comparator)',
    input: { generatedText: G('a', 'b'), committedText: G('a', 'b') },
    expect: 'fresh',
  },
  {
    name: 'empty generated -> vacuous (kills: git-cliff error swallowed to "")',
    input: { generatedText: '', committedText: G('a', 'b') },
    expect: 'vacuous',
  },
  {
    name: 'empty committed -> vacuous (kills: zero-parse side scored as fresh)',
    input: { generatedText: G('a', 'b'), committedText: '' },
    expect: 'vacuous',
  },
  {
    name: 'parser returns nothing -> vacuous (kills: parseChangelogEntries -> empty map)',
    input: { generatedText: 'no headings here\n', committedText: 'no headings here\n' },
    expect: 'vacuous',
  },
  {
    name: 'at the entry threshold but young -> lagging (kills: bare count threshold)',
    input: {
      generatedText: G(...seq(LAG_FAIL_ENTRIES + 1)),
      committedText: G('entry 0'),
      ageDays: LAG_FAIL_AGE_DAYS - 1,
    },
    expect: 'lagging',
  },
  {
    name: 'at both thresholds -> stale (kills: > instead of >= on either signal)',
    input: {
      generatedText: G(...seq(LAG_FAIL_ENTRIES + 1)),
      committedText: G('entry 0'),
      ageDays: LAG_FAIL_AGE_DAYS,
    },
    expect: 'stale',
  },
  {
    name: 'old but small lag -> lagging (kills: age-only rule)',
    input: {
      generatedText: G(...seq(LAG_FAIL_ENTRIES)),
      committedText: G('entry 0'),
      ageDays: 365,
    },
    expect: 'lagging',
  },
  {
    name: 'undatable lag -> lagging, never stale (kills: null age coerced to 0/Infinity)',
    input: {
      generatedText: G(...seq(LAG_FAIL_ENTRIES + 1)),
      committedText: G('entry 0'),
      ageDays: null,
    },
    expect: 'lagging',
  },
  {
    name: 'extra above the floor -> drift (kills: dropped extra branch)',
    input: { generatedText: G('a'), committedText: G('a', ...seq(EXTRA_HARD_FLOOR + 1)) },
    expect: 'drift',
  },
  {
    name: 'extra at the floor -> lagging advisory (kills: unconditional extra red)',
    input: { generatedText: G('a'), committedText: G('a', ...seq(EXTRA_HARD_FLOOR)) },
    expect: 'lagging',
  },
  {
    name: 'drift beats stale (kills: verdict order that checks missing first)',
    input: {
      generatedText: G(...seq(LAG_FAIL_ENTRIES + 1)),
      committedText: G('entry 0', ...seq(EXTRA_HARD_FLOOR + 1, 100)),
      ageDays: LAG_FAIL_AGE_DAYS + 10,
    },
    expect: 'drift',
  },
  {
    name: 'entry moved between groups -> not fresh (kills: group dropped from the key)',
    input: {
      generatedText: '# Changelog\n\n### Features\n\n- x\n',
      committedText: '# Changelog\n\n### Fixes\n\n- x\n',
    },
    expect: 'lagging',
  },
  {
    name: 'duplicate entry line counts twice (kills: Set instead of multiset)',
    input: { generatedText: G('dup', 'dup'), committedText: G('dup') },
    expect: 'fresh',
    alsoExpectLag: 1,
  },
  {
    name: 'same entries, different rendering -> rendering (kills: entry-set-only comparator)',
    input: {
      generatedText: G('a', 'b'),
      committedText: '# Changelog\n\n### Features\n\n- a\n\n- b\n',
    },
    expect: 'rendering',
  },
  {
    name: 'trailing whitespace and no final newline are not drift (kills: raw string compare)',
    input: {
      generatedText: G('a', 'b'),
      committedText: '# Changelog\n\n### Features\n\n- a  \n- b',
    },
    expect: 'fresh',
  },
];

// The comparator is INJECTED so the teeth can be proven to bite: the gating suite calls
// runSelfTest with a deliberately wrong comparator and asserts it reports failures.
// Without that seam, `return { ok: true, failures: [] }` is an undetectable neutering of
// the entire inline fixture table — a surviving mutant when this was bite-proofed.
export function runSelfTest(classify = classifyChangelogDrift) {
  const failures = [];
  for (const testCase of SELF_TEST_CASES) {
    let verdict;
    let lag;
    try {
      const result = classify(testCase.input);
      verdict = result.verdict;
      lag = result.lag;
    } catch (err) {
      failures.push(`${testCase.name}: threw ${err?.message ?? String(err)}`);
      continue;
    }
    if (verdict !== testCase.expect) {
      failures.push(`${testCase.name}: expected ${testCase.expect}, got ${verdict}`);
    }
    if (testCase.alsoExpectLag !== undefined && lag !== testCase.alsoExpectLag) {
      failures.push(`${testCase.name}: expected lag ${testCase.alsoExpectLag}, got ${lag}`);
    }
  }
  return { ok: failures.length === 0, failures, cases: SELF_TEST_CASES.length };
}

// ---------------------------------------------------------------------------
// Imperative shell
// ---------------------------------------------------------------------------

const die = (code, message) => {
  console.error(LOG_PREFIX + message);
  process.exit(code);
};

// Paths resolve from THIS file, never process.cwd() — the nightly job's working
// directory is not this script's contract.
const scriptDir = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(scriptDir, '..');

// Errors are never swallowed to '': a swallowed generation is the single most dangerous
// vacuous green (an empty "generated" side means zero missing entries, i.e. "fresh").
function git(args) {
  return execFileSync('git', args, {
    cwd: repoRoot,
    encoding: 'utf8',
    maxBuffer: 64 * 1024 * 1024,
  });
}

function main(argv) {
  for (const arg of argv) {
    if (arg !== '--check')
      die(2, `unknown argument '${arg}' — usage: node scripts/changelog-freshness.mjs [--check]`);
  }

  // 1. The teeth, before any I/O.
  const selfTest = runSelfTest();
  if (!selfTest.ok) {
    die(
      2,
      `self-test FAILED (${selfTest.failures.length} of ${selfTest.cases} teeth did not bite):\n${selfTest.failures.join('\n')}`,
    );
  }
  if (selfTest.cases < 10)
    die(2, `self-test table has only ${selfTest.cases} cases — the teeth have been removed`);

  // 2. The sibling suite cannot be silently emptied (`node --test` exits 0 on zero tests).
  let siblingSource;
  try {
    siblingSource = readFileSync(path.join(scriptDir, SIBLING_TEST_FILE), 'utf8');
  } catch (err) {
    die(2, `cannot read ${SIBLING_TEST_FILE}: ${err?.message ?? String(err)}`);
  }
  const siblingTests = siblingSource.split(SIBLING_TEST_MARKER).length - 1;
  if (siblingTests < MIN_SIBLING_TESTS) {
    die(
      2,
      `${SIBLING_TEST_FILE} defines ${siblingTests} tests, floor is ${MIN_SIBLING_TESTS} — the suite has been weakened`,
    );
  }

  // 3. A shallow checkout makes git-cliff emit ONE entry, silently, exit 0, no warning.
  // `fetch-depth: 0` in the workflow is one deletable YAML line; this assertion is not.
  if (git(['rev-parse', '--is-shallow-repository']).trim() !== 'false') {
    die(
      2,
      'shallow checkout — git-cliff would generate a truncated changelog; the workflow needs `fetch-depth: 0`',
    );
  }

  // 4. Generate. `git cliff` with no -o writes to stdout and never reads CHANGELOG.md,
  // so this cannot degenerate into comparing the file with itself.
  let generatedText;
  try {
    generatedText = git(['cliff']);
  } catch (err) {
    die(2, `git cliff failed: ${err?.message ?? String(err)}`);
  }
  const generated = parseChangelogEntries(generatedText);
  if (generated.size < MIN_GENERATED_ENTRIES) {
    die(
      2,
      `generation produced ${generated.size} entries, floor is ${MIN_GENERATED_ENTRIES} — truncated history or a broken generator, not a freshness result`,
    );
  }

  // 5. Prove the generated side really came from git history: the newest Conventional
  // Commit on HEAD must appear in it. This is what kills a self-compare — a stale
  // committed file cannot contain the newest subject's entry.
  // The FULL log, not a window: the mapped-fraction guard below compares against every
  // entry the generation contains, and a windowed log would make old entries look
  // unmappable.
  const log = git(['log', '--format=%cI%x1f%s']);
  const commits = log
    .split('\n')
    .filter((line) => line.length > 0)
    .map((line) => {
      const [iso, subject] = line.split('\x1f');
      return { iso, subject };
    });
  const newest = commits.map((c) => entryTextForSubject(c.subject)).find((t) => t !== null);
  if (newest === undefined)
    die(2, 'no Conventional Commit found on HEAD — cannot validate the generation');
  const generatedTexts = new Set([...generated.keys()].map(entryTextFromKey));
  if (!generatedTexts.has(newest)) {
    die(
      2,
      `the generated changelog does not contain the newest commit's entry (${newest}) — it did not come from git history`,
    );
  }

  // 5b. The subject->entry transform must still track git-cliff's rendering, or the age
  // arm of the conjunction silently dies (see MIN_MAPPED_FRACTION).
  const subjectTexts = new Set(
    commits.map((c) => entryTextForSubject(c.subject)).filter((t) => t !== null),
  );
  const mapped = [...generatedTexts].filter((t) => subjectTexts.has(t)).length;
  const fraction = mapped / generatedTexts.size;
  if (fraction < MIN_MAPPED_FRACTION) {
    die(
      2,
      `only ${mapped}/${generatedTexts.size} (${(fraction * 100).toFixed(1)}%) generated entries map back to a commit subject, floor ${(MIN_MAPPED_FRACTION * 100).toFixed(0)}% — entryTextForSubject no longer tracks the cliff.toml template, so the age signal cannot be trusted`,
    );
  }

  // 6. The committed side must be a changelog this script can reason about.
  let committedText;
  try {
    committedText = readFileSync(path.join(repoRoot, 'CHANGELOG.md'), 'utf8');
  } catch (err) {
    die(2, `cannot read CHANGELOG.md: ${err?.message ?? String(err)}`);
  }
  const problems = findStructuralProblems(committedText);
  if (problems.length > 0) die(2, `CHANGELOG.md is malformed:\n${problems.join('\n')}`);

  // 7. Classify.
  const preliminary = classifyChangelogDrift({ generatedText, committedText });
  const ageDays = oldestMissingAgeDays({
    missingTexts: preliminary.missing.map(entryTextFromKey),
    commits,
    nowMs: Date.now(),
  });
  const result = classifyChangelogDrift({ generatedText, committedText, ageDays });
  console.log(formatVerdict(result));
  process.exit(exitCodeForVerdict(result.verdict));
}

// Main-guard: the sibling test file imports this module, and an unguarded shell would
// shell out to git and process.exit() mid-test-run.
if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main(process.argv.slice(2));
}
